class Solution
{
public:
    int trap(vector<int> &height){
        int maxi=-1;
        int maxInd=-1;
        for(int i=0;i<height.size();i++){
            if(height[i]>maxi){
                maxi=height[i];
                maxInd=i;
            }
        }
        int totalWater=0;
        int leftMax=height[0];
        for(int i=1;i<maxInd;i++){
            totalWater+=max(leftMax-height[i],0);
            leftMax=max(leftMax,height[i]);
        }
        int rightMax=height[height.size()-1];
        for(int i=height.size()-2;i>maxInd;i--){
            totalWater+=max(rightMax-height[i],0);
            rightMax=max(rightMax,height[i]);
        }
        return totalWater;
    }
};
```

